import React from 'react';
import {
  EXTERNAL_SYNC_AUTO_REFRESH_CHANGE_EVENT,
  readExternalSyncAutoRefreshSettings,
  type ExternalSyncAutoRefreshSettings,
  writeExternalSyncAutoRefreshSettings,
} from './externalSyncAutoRefreshSettings';

export function useExternalSyncAutoRefreshSettings() {
  const [settings, setSettingsState] = React.useState<ExternalSyncAutoRefreshSettings>(() =>
    readExternalSyncAutoRefreshSettings(),
  );

  React.useEffect(() => {
    const onChange = (event: Event) => {
      const detail = (event as CustomEvent<ExternalSyncAutoRefreshSettings>).detail;
      if (detail) {
        setSettingsState(detail);
        return;
      }
      setSettingsState(readExternalSyncAutoRefreshSettings());
    };

    window.addEventListener(EXTERNAL_SYNC_AUTO_REFRESH_CHANGE_EVENT, onChange);
    return () => window.removeEventListener(EXTERNAL_SYNC_AUTO_REFRESH_CHANGE_EVENT, onChange);
  }, []);

  const setSettings = React.useCallback((next: ExternalSyncAutoRefreshSettings) => {
    writeExternalSyncAutoRefreshSettings(next);
    setSettingsState(readExternalSyncAutoRefreshSettings());
  }, []);

  const intervalMs = settings.enabled ? settings.intervalSeconds * 1000 : 0;

  return { settings, setSettings, intervalMs };
}
