import React from 'react';
import { Button } from '../../../ui';
import { jobsService, type LegacyCashVoucherRepostPreview } from '../../../services/jobs';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';

type Props = {
  legacyRepostPaused?: boolean;
  onRunStarted: (runId: string) => void;
};

const ExternalSyncLegacyCashPanel: React.FC<Props> = ({ legacyRepostPaused, onRunStarted }) => {
  const toast = useAppToast();
  const [preview, setPreview] = React.useState<LegacyCashVoucherRepostPreview | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [running, setRunning] = React.useState(false);
  const [searched, setSearched] = React.useState(false);

  const loadPreview = React.useCallback(() => {
    setLoadingPreview(true);
    setSearched(true);
    jobsService
      .getLegacyCashVoucherRepostPreview()
      .then(setPreview)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [toast]);

  const handleRun = React.useCallback(() => {
    if (legacyRepostPaused) {
      toast.warning('Ghi sổ batch phiếu cũ đang tạm dừng — bỏ tick «Tạm dừng ghi sổ batch phiếu cũ».');
      return;
    }
    if (!searched || !preview?.eligibleCount) {
      toast.warning('Bấm Tìm trước — không có phiếu thu/chi cũ cần ghi sổ.');
      return;
    }
    const ok = window.confirm(
      `Ghi sổ ${preview.eligibleCount.toLocaleString('vi-VN')} phiếu thu/chi REVA FM (Draft · chưa có sổ)?\n\n` +
        `PT: ${preview.receiptCount.toLocaleString('vi-VN')} · PC: ${preview.paymentCount.toLocaleString('vi-VN')}`,
    );
    if (!ok) return;

    setRunning(true);
    jobsService
      .triggerLegacyCashVoucherRepost()
      .then((result) => {
        if (result.runId) {
          toast.info(
            `Đã tạo job ghi sổ ${result.documentsEnqueued.toLocaleString('vi-VN')} phiếu — theo dõi run bên dưới.`,
          );
          onRunStarted(result.runId);
          return;
        }
        toast.success(`Đã lên lịch ${result.documentsEnqueued.toLocaleString('vi-VN')} phiếu.`);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRunning(false));
  }, [legacyRepostPaused, searched, preview, toast, onRunStarted]);

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '12px 16px',
        border: '1px solid #e2e8f0',
        borderRadius: 8,
        background: legacyRepostPaused ? '#f1f5f9' : '#f8fafc',
        opacity: legacyRepostPaused ? 0.85 : 1,
      }}
      data-testid="legacy-cash-voucher-repost-panel"
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'center', justifyContent: 'space-between' }}>
        <div>
          <strong>Ghi sổ phiếu thu/chi sync cũ</strong>
          <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
            Phiếu REVA FM <code>FM-*</code> · Draft · chưa có dòng sổ cái — enqueue job ghi sổ (High).
          </p>
          {loadingPreview ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>Đang đếm…</p>
          ) : preview && searched ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>
              Đủ điều kiện: <strong>{preview.eligibleCount.toLocaleString('vi-VN')}</strong>
              {' '}(PT {preview.receiptCount.toLocaleString('vi-VN')} · PC{' '}
              {preview.paymentCount.toLocaleString('vi-VN')})
            </p>
          ) : (
            <p style={{ margin: '6px 0 0', fontSize: 13, color: '#64748b' }}>Bấm Tìm để quét phiếu thu/chi thiếu ghi sổ.</p>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8 }}>
          <Button type="button" variant="secondary" onClick={loadPreview} disabled={loadingPreview || running} data-testid="legacy-repost-refresh">
            Tìm
          </Button>
          <Button
            type="button"
            onClick={handleRun}
            disabled={running || loadingPreview || !searched || !preview?.eligibleCount || legacyRepostPaused}
            data-testid="legacy-repost-trigger"
          >
            {running ? 'Đang tạo job…' : 'Ghi sổ tất cả'}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default ExternalSyncLegacyCashPanel;
