import type { DataSyncRunListItem } from '../../services/jobs';

/** View key — route segment sau /admin/jobs/external-runs/ */
export type ExternalSyncJobView =
  | 'sync'
  | 'missing-ledger'
  | 'legacy-cash'
  | 'legacy-invoice'
  | 'vat-refill';

export const EXTERNAL_SYNC_JOB_VIEW_META: Record<
  ExternalSyncJobView,
  {
    path: string;
    title: string;
    shortLabel: string;
    trigger: string | null;
    setName: string | null;
    listHint: string;
  }
> = {
  sync: {
    path: '/admin/jobs/external-runs',
    title: 'Theo dõi sync REVA FM',
    shortLabel: 'Sync REVA',
    trigger: null,
    setName: null,
    listHint: 'Run pull HĐ/PT/PC từ REVA FM — connector reva-fm-*.',
  },
  'missing-ledger': {
    path: '/admin/jobs/external-runs/missing-ledger',
    title: 'Re-Post',
    shortLabel: 'Re-Post',
    trigger: 'MissingLedgerRepost',
    setName: 'missing-ledger-repost-review',
    listHint: 'Run Re-Post HĐ / PT / PC theo khoảng ngày và loại CT.',
  },
  'legacy-cash': {
    path: '/admin/jobs/external-runs/legacy-cash',
    title: 'Ghi sổ phiếu thu/chi sync cũ',
    shortLabel: 'PT/PC cũ',
    trigger: 'LegacyCashRepost',
    setName: 'legacy-cash-voucher-repost',
    listHint: 'Run ghi sổ phiếu FM-* Draft chưa có dòng sổ cái.',
  },
  'legacy-invoice': {
    path: '/admin/jobs/external-runs/legacy-invoice',
    title: 'Ghi sổ HĐ POS thiếu công nợ',
    shortLabel: 'HĐ CONGNO',
    trigger: 'LegacyInvoiceRepost',
    setName: 'legacy-sales-invoice-receivable-repost',
    listHint: 'Run ghi sổ HĐ Draft thiếu GL công nợ (Nợ 131 · Có 511).',
  },
  'vat-refill': {
    path: '/admin/jobs/external-runs/vat-refill',
    title: 'Re-fill VAT HĐ POS',
    shortLabel: 'Re-fill VAT',
    trigger: 'PosVatRefill',
    setName: 'pos-vat-refill',
    listHint: 'Run re-import FM ChiTietHoaDon — áp lại tách thuế VAT.',
  },
};

const JOB_ACTION_TRIGGERS = new Set(
  Object.values(EXTERNAL_SYNC_JOB_VIEW_META)
    .map((m) => m.trigger)
    .filter((t): t is string => Boolean(t)),
);

const JOB_ACTION_SETS = new Set(
  Object.values(EXTERNAL_SYNC_JOB_VIEW_META)
    .map((m) => m.setName)
    .filter((s): s is string => Boolean(s)),
);

export const EXTERNAL_SYNC_JOB_VIEW_ORDER: ExternalSyncJobView[] = [
  'sync',
  'missing-ledger',
  'legacy-cash',
  'legacy-invoice',
  'vat-refill',
];

export function resolveExternalSyncJobView(pathname: string): ExternalSyncJobView {
  const normalized = pathname.replace(/\/+$/, '') || '/';
  const base = '/admin/jobs/external-runs';
  if (normalized === base) return 'sync';
  for (const view of EXTERNAL_SYNC_JOB_VIEW_ORDER) {
    if (view === 'sync') continue;
    const path = EXTERNAL_SYNC_JOB_VIEW_META[view].path;
    if (normalized === path || normalized.startsWith(`${path}/`)) return view;
  }
  return 'sync';
}

export function matchesExternalSyncJobView(
  run: DataSyncRunListItem,
  view: ExternalSyncJobView,
): boolean {
  if (view === 'sync') {
    if (JOB_ACTION_TRIGGERS.has(run.trigger)) return false;
    if (run.setsRequested.some((s) => JOB_ACTION_SETS.has(s))) return false;
    return true;
  }
  const meta = EXTERNAL_SYNC_JOB_VIEW_META[view];
  if (meta.trigger && run.trigger === meta.trigger) return true;
  if (meta.setName && run.setsRequested.includes(meta.setName)) return true;
  return false;
}

export function filterRunsForView(
  runs: DataSyncRunListItem[],
  view: ExternalSyncJobView,
): DataSyncRunListItem[] {
  return runs.filter((r) => matchesExternalSyncJobView(r, view));
}

/** Chọn tab view phù hợp khi deep-link ?runId=… */
export function resolveViewFromRun(run: DataSyncRunListItem): ExternalSyncJobView {
  for (const key of EXTERNAL_SYNC_JOB_VIEW_ORDER) {
    if (key === 'sync') continue;
    if (matchesExternalSyncJobView(run, key)) return key;
  }
  return 'sync';
}

export function externalSyncRunHref(view: ExternalSyncJobView, runId?: string | null): string {
  const base = EXTERNAL_SYNC_JOB_VIEW_META[view].path;
  if (!runId) return base;
  return `${base}?runId=${encodeURIComponent(runId)}`;
}
