export const EXTERNAL_SYNC_AUTO_REFRESH_STORAGE_KEY = 'linm.admin.externalSyncAutoRefresh.v1';

export const EXTERNAL_SYNC_AUTO_REFRESH_CHANGE_EVENT = 'linm:external-sync-auto-refresh-change';

export const EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS = {
  enabled: true,
  intervalSeconds: 4,
} as const;

export const EXTERNAL_SYNC_AUTO_REFRESH_MIN_SECONDS = 3;
export const EXTERNAL_SYNC_AUTO_REFRESH_MAX_SECONDS = 300;

export type ExternalSyncAutoRefreshSettings = {
  enabled: boolean;
  intervalSeconds: number;
};

export function clampIntervalSeconds(value: number): number {
  if (!Number.isFinite(value)) {
    return EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS.intervalSeconds;
  }
  return Math.min(
    EXTERNAL_SYNC_AUTO_REFRESH_MAX_SECONDS,
    Math.max(EXTERNAL_SYNC_AUTO_REFRESH_MIN_SECONDS, Math.round(value)),
  );
}

export function readExternalSyncAutoRefreshSettings(): ExternalSyncAutoRefreshSettings {
  if (typeof window === 'undefined') {
    return { ...EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS };
  }

  try {
    const raw = window.localStorage.getItem(EXTERNAL_SYNC_AUTO_REFRESH_STORAGE_KEY);
    if (!raw) {
      return { ...EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS };
    }

    const parsed = JSON.parse(raw) as Partial<ExternalSyncAutoRefreshSettings>;
    return {
      enabled: parsed.enabled ?? EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS.enabled,
      intervalSeconds: clampIntervalSeconds(
        parsed.intervalSeconds ?? EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS.intervalSeconds,
      ),
    };
  } catch {
    return { ...EXTERNAL_SYNC_AUTO_REFRESH_DEFAULTS };
  }
}

export function writeExternalSyncAutoRefreshSettings(settings: ExternalSyncAutoRefreshSettings): void {
  const next: ExternalSyncAutoRefreshSettings = {
    enabled: settings.enabled,
    intervalSeconds: clampIntervalSeconds(settings.intervalSeconds),
  };

  if (typeof window !== 'undefined') {
    window.localStorage.setItem(EXTERNAL_SYNC_AUTO_REFRESH_STORAGE_KEY, JSON.stringify(next));
    window.dispatchEvent(
      new CustomEvent<ExternalSyncAutoRefreshSettings>(EXTERNAL_SYNC_AUTO_REFRESH_CHANGE_EVENT, {
        detail: next,
      }),
    );
  }
}

export function formatExternalSyncAutoRefreshHint(settings: ExternalSyncAutoRefreshSettings): string {
  if (!settings.enabled) {
    return 'Run đang chạy — tự làm mới đã tắt. Bấm Làm mới trên danh sách run hoặc checkpoint khi cần.';
  }
  return `Run đang chạy — tự làm mới mỗi ${settings.intervalSeconds} giây (hoặc bấm Làm mới trên danh sách run).`;
}
